PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE departments (id TEXT PRIMARY KEY, name TEXT NOT NULL, is_active INTEGER NOT NULL CHECK(is_active IN(0,1)));
CREATE TABLE lines (id TEXT PRIMARY KEY, department_id TEXT NOT NULL REFERENCES departments(id), name TEXT NOT NULL, is_active INTEGER NOT NULL CHECK(is_active IN(0,1)), remark TEXT NOT NULL DEFAULT '', UNIQUE(id, department_id));
CREATE TABLE brands (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL CHECK(is_active IN(0,1)), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE machines (
 id TEXT PRIMARY KEY, code TEXT NOT NULL, normalized_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
 department_id TEXT NOT NULL REFERENCES departments(id), line_id TEXT NOT NULL,
 manufacturer TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', serial_no TEXT NOT NULL DEFAULT '', machine_type TEXT NOT NULL DEFAULT '',
 install_date TEXT NOT NULL DEFAULT '', criticality TEXT NOT NULL, status TEXT NOT NULL, location_detail TEXT NOT NULL DEFAULT '',
 photo_file_id TEXT NOT NULL DEFAULT '', photo_file_name TEXT NOT NULL DEFAULT '', manual_url TEXT NOT NULL DEFAULT '', remark TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL,
 is_active INTEGER NOT NULL CHECK(is_active IN(0,1)), version INTEGER NOT NULL CHECK(version>0), request_id TEXT NOT NULL, line_order INTEGER CHECK(line_order IS NULL OR line_order > 0),
 FOREIGN KEY(line_id, department_id) REFERENCES lines(id, department_id)
);
CREATE TABLE parts (
 id TEXT PRIMARY KEY, part_number TEXT NOT NULL, description TEXT NOT NULL, brand_id TEXT REFERENCES brands(id), legacy_brand_name TEXT NOT NULL DEFAULT '',
 price_minor INTEGER CHECK(price_minor IS NULL OR (price_minor>=0 AND price_minor<=99999999999900)),
 store_code TEXT NOT NULL DEFAULT '', lifespan_years REAL CHECK(lifespan_years IS NULL OR (lifespan_years>=0 AND lifespan_years<=999)), notes TEXT NOT NULL DEFAULT '',
 picture_source TEXT NOT NULL DEFAULT '', thumbnail_source TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), request_id TEXT NOT NULL
);
CREATE TABLE id_counters (kind TEXT PRIMARY KEY, value INTEGER NOT NULL CHECK(value>=0));
CREATE TABLE requests (
 key TEXT PRIMARY KEY, actor TEXT NOT NULL, operation TEXT NOT NULL, payload_hash TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN('PENDING','DONE')), response_json TEXT, created_at TEXT NOT NULL
);
CREATE TABLE audit_events (
 sequence INTEGER PRIMARY KEY AUTOINCREMENT, request_key TEXT NOT NULL UNIQUE REFERENCES requests(key),
 actor TEXT NOT NULL, operation TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL
);
CREATE TABLE mutation_guards (id TEXT PRIMARY KEY, changed INTEGER NOT NULL CHECK(changed=1));
CREATE TABLE image_operations (
 id TEXT PRIMARY KEY, request_key TEXT NOT NULL, slot TEXT NOT NULL, folder_id TEXT NOT NULL,
 file_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, mime TEXT NOT NULL, payload_hash TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN('RESERVED','UPLOADED','ATTACHED','REVIEW')),
 created_at TEXT NOT NULL, UNIQUE(request_key,slot)
);
CREATE TABLE migration_runs (id TEXT PRIMARY KEY, snapshot_hash TEXT NOT NULL, imported_at TEXT NOT NULL, report_json TEXT NOT NULL);
CREATE TABLE user_roles (email TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN('viewer','editor','admin')));
CREATE TABLE equipment_records (
  id TEXT PRIMARY KEY,
  equipment_id TEXT NOT NULL,
  machine_id TEXT NOT NULL REFERENCES machines(id),
  part_id TEXT NOT NULL REFERENCES parts(id),
  label TEXT NOT NULL DEFAULT '',
  quantity INTEGER NOT NULL CHECK(quantity > 0),
  installed_at TEXT NOT NULL DEFAULT '',
  due_mode TEXT NOT NULL CHECK(due_mode IN('PART_LIFE', 'MANUAL')),
  manual_expiry_date TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  record_status TEXT NOT NULL CHECK(record_status IN('ACTIVE', 'REPLACED', 'REMOVED', 'HISTORY')),
  ended_at TEXT NOT NULL DEFAULT '',
  previous_record_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL DEFAULT '',
  version INTEGER NOT NULL CHECK(version > 0),
  operation_id TEXT NOT NULL
);
CREATE TABLE equipment_operations (
  id TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL,
  machine_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN('PREPARED', 'COMMITTED', 'FAILED')),
  plan_json TEXT NOT NULL,
  result_json TEXT NOT NULL,
  created_at TEXT NOT NULL,
  session_ref TEXT NOT NULL DEFAULT ''
);
CREATE TABLE app_users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('admin', 'editor', 'viewer')),
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, user_type TEXT NOT NULL DEFAULT 'permanent', expires_at TEXT, permissions_json TEXT NOT NULL DEFAULT '{}', force_password_change INTEGER NOT NULL DEFAULT 0);
CREATE TABLE app_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES app_users(id),
  token_hash TEXT NOT NULL UNIQUE,
  expires_at INTEGER NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE machine_types (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  normalized_name TEXT NOT NULL UNIQUE,
  is_active INTEGER NOT NULL CHECK(is_active IN(0, 1)),
  version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE announcements (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  media_type TEXT NOT NULL CHECK(media_type IN('image','video')),
  file_id TEXT NOT NULL DEFAULT '',
  file_name TEXT NOT NULL DEFAULT '',
  file_url TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE announcement_settings (
  id TEXT PRIMARY KEY DEFAULT 'main',
  company_last_incident TEXT NOT NULL DEFAULT '2023-10-28',
  company_target_days INTEGER NOT NULL DEFAULT 1200,
  dept_last_incident TEXT NOT NULL DEFAULT '2016-09-12',
  dept_target_days INTEGER NOT NULL DEFAULT 3802,
  slide_interval_seconds INTEGER NOT NULL DEFAULT 60,
  show_clock INTEGER NOT NULL DEFAULT 1 CHECK(show_clock IN(0,1)),
  show_safety INTEGER NOT NULL DEFAULT 1 CHECK(show_safety IN(0,1)),
  updated_at TEXT NOT NULL
, force_media_id TEXT DEFAULT '', force_timestamp INTEGER DEFAULT 0, current_media_id TEXT DEFAULT '');
CREATE TABLE pm_cycles (
  id TEXT PRIMARY KEY,
  department_id TEXT NOT NULL REFERENCES departments(id),
  line_id TEXT NOT NULL,
  year INTEGER NOT NULL,
  round_no INTEGER NOT NULL CHECK(round_no >= 1 AND round_no <= 5),
  target_month TEXT NOT NULL DEFAULT '',
  plan_date TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE', 'CLOSED', 'ARCHIVED')),
  notes TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  UNIQUE(line_id, year, round_no)
);
CREATE TABLE pm_machine_orders (
  id TEXT PRIMARY KEY,
  cycle_id TEXT NOT NULL REFERENCES pm_cycles(id) ON DELETE CASCADE,
  machine_id TEXT NOT NULL REFERENCES machines(id),
  order_no TEXT NOT NULL DEFAULT '',
  pr_no TEXT NOT NULL DEFAULT '',
  pr_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(pr_status IN('PENDING', 'ORDER_ASSIGNED', 'PR_OPENED', 'COMPLETED')),
  notes TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL, budget_amount REAL NOT NULL DEFAULT 0,
  UNIQUE(cycle_id, machine_id)
);
CREATE TABLE pm_expenses (
  id TEXT PRIMARY KEY,
  plant TEXT NOT NULL DEFAULT '1200',
  gl_account TEXT NOT NULL DEFAULT '',
  cost_center TEXT NOT NULL DEFAULT '',
  machine_code TEXT NOT NULL,
  machine_id TEXT,
  department_id TEXT DEFAULT '',
  line_id TEXT DEFAULT '',
  pm_order_no TEXT NOT NULL DEFAULT '',
  doc_date TEXT NOT NULL,
  doc_no TEXT NOT NULL DEFAULT '',
  movement_type TEXT NOT NULL DEFAULT '261',
  material_no TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  quantity REAL NOT NULL DEFAULT 0,
  uom TEXT NOT NULL DEFAULT 'EA',
  unit_price REAL NOT NULL DEFAULT 0,
  amount REAL NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'THB',
  order_type TEXT NOT NULL DEFAULT '1PMO',
  po_no TEXT NOT NULL DEFAULT '',
  functional_loc TEXT NOT NULL DEFAULT '',
  work_center TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  imported_at TEXT NOT NULL,
  imported_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE pm_line_budgets (
  id TEXT PRIMARY KEY,
  line_id TEXT NOT NULL,
  department_id TEXT NOT NULL,
  year INTEGER NOT NULL,
  budget_amount REAL NOT NULL DEFAULT 0,
  notes TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  UNIQUE(line_id, year)
);
CREATE TABLE pr_tracker_items (
  id TEXT PRIMARY KEY,
  created_date TEXT NOT NULL,
  doc_type TEXT NOT NULL DEFAULT 'PR' CHECK(doc_type IN('PR', 'STORE')),
  doc_no TEXT NOT NULL DEFAULT '',
  department_id TEXT NOT NULL DEFAULT '',
  line_id TEXT NOT NULL DEFAULT '',
  machine_id TEXT DEFAULT '',
  machine_code TEXT NOT NULL DEFAULT '',
  order_no TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL,
  qty REAL NOT NULL DEFAULT 1,
  unit TEXT NOT NULL DEFAULT 'ชิ้น',
  price REAL DEFAULT NULL,
  po_no TEXT NOT NULL DEFAULT '',
  delivery_date TEXT NOT NULL DEFAULT '',
  is_archived INTEGER NOT NULL DEFAULT 0,
  archived_at TEXT DEFAULT NULL,
  archived_by TEXT DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE pm_aircooling_units (
  id TEXT PRIMARY KEY,
  dept TEXT NOT NULL DEFAULT '',
  id_tag TEXT NOT NULL DEFAULT '',
  line TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  brand TEXT NOT NULL DEFAULT '',
  power REAL NOT NULL DEFAULT 0,
  serial TEXT NOT NULL DEFAULT '',
  details TEXT NOT NULL DEFAULT '',
  note TEXT NOT NULL DEFAULT '',
  last_clean_date TEXT NOT NULL DEFAULT '',
  next_clean_date TEXT NOT NULL DEFAULT '',
  image_url TEXT NOT NULL DEFAULT '',
  drive_file_id TEXT NOT NULL DEFAULT '',
  report_status TEXT NOT NULL DEFAULT '',
  report_info TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (DATETIME('now', '+7 hours')),
  updated_at TEXT NOT NULL DEFAULT (DATETIME('now', '+7 hours'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX machines_location ON machines(department_id,line_id,is_active);
CREATE INDEX parts_number ON parts(part_number);
CREATE INDEX parts_brand ON parts(brand_id);
CREATE INDEX idx_equipment_machine_status ON equipment_records(machine_id, record_status);
CREATE INDEX idx_equipment_part ON equipment_records(part_id);
CREATE INDEX idx_equipment_equipment_id ON equipment_records(equipment_id);
CREATE INDEX idx_operations_machine ON equipment_operations(machine_id);
CREATE INDEX idx_users_username ON app_users(username);
CREATE INDEX idx_sessions_token_hash ON app_sessions(token_hash);
CREATE INDEX idx_sessions_expires_at ON app_sessions(expires_at);
CREATE INDEX idx_equipment_machine_status_part_created
ON equipment_records(machine_id, record_status, part_id, created_at);
CREATE INDEX idx_equipment_machine_equipment_created
ON equipment_records(machine_id, equipment_id, created_at DESC);
CREATE INDEX idx_operations_machine_status_created
ON equipment_operations(machine_id, status, created_at DESC);
CREATE INDEX machines_line_order ON machines(department_id, line_id, line_order, code);
CREATE INDEX idx_pm_cycles_line_year ON pm_cycles(line_id, year);
CREATE INDEX idx_pm_machine_orders_cycle ON pm_machine_orders(cycle_id);
CREATE INDEX idx_pm_machine_orders_machine ON pm_machine_orders(machine_id);
CREATE INDEX idx_pm_expenses_date ON pm_expenses(doc_date DESC);
CREATE INDEX idx_pm_expenses_machine ON pm_expenses(machine_code);
CREATE INDEX idx_pm_expenses_line ON pm_expenses(line_id);
CREATE INDEX idx_pm_expenses_dept ON pm_expenses(department_id);
CREATE INDEX idx_pm_expenses_order ON pm_expenses(pm_order_no);
CREATE INDEX idx_pr_tracker_date ON pr_tracker_items(created_date DESC);
CREATE INDEX idx_pr_tracker_dept ON pr_tracker_items(department_id);
CREATE INDEX idx_pr_tracker_line ON pr_tracker_items(line_id);
CREATE INDEX idx_pr_tracker_machine ON pr_tracker_items(machine_code);
CREATE INDEX idx_pr_tracker_order ON pr_tracker_items(order_no);
CREATE INDEX idx_pr_tracker_doc_no ON pr_tracker_items(doc_no);
CREATE INDEX idx_pr_tracker_po_no ON pr_tracker_items(po_no);
CREATE INDEX idx_pr_tracker_archived ON pr_tracker_items(is_archived);
CREATE INDEX idx_pm_aircooling_dept ON pm_aircooling_units(dept);
CREATE INDEX idx_pm_aircooling_line ON pm_aircooling_units(line);
CREATE INDEX idx_pm_aircooling_id_tag ON pm_aircooling_units(id_tag);
CREATE INDEX idx_pm_aircooling_next_clean ON pm_aircooling_units(next_clean_date);
CREATE INDEX idx_pm_aircooling_brand ON pm_aircooling_units(brand);
CREATE INDEX idx_pm_aircooling_report_status ON pm_aircooling_units(report_status);
